fn validate_reserve_rule_contract(root: &Path) -> Result<(), String> {
    for path in [
        RESERVE_RULE_CONTRACT_JSON_PATH,
        RESERVE_RULE_CONTRACT_SCHEMA_PATH,
        RESERVE_RULE_CONTRACT_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!("missing reserve rule contract artifact: {path}"));
        }
    }

    let text = fs::read_to_string(root.join(RESERVE_RULE_CONTRACT_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let contract: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&contract, "record_id")? != "reserve-rule-contract:v1"
        || string_field(&contract, "record_family")? != "reserve_rule_contract"
        || int_field(&contract, "pulse")? != 102
        || string_field(&contract, "program_lane_target_cost_contract_path")?
            != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
        || string_field(&contract, "balance_guardrail_path")?
            != "docs/research/2026-06-23-balance-rule-guardrail-spec.md"
        || string_field(&contract, "rate_adjustment_operating_model_path")?
            != "docs/research/2026-06-24-rate-adjustment-operating-model.md"
        || string_field(&contract, "solver_input_inventory_path")?
            != SOLVER_INPUT_INVENTORY_JSON_PATH
    {
        return Err("reserve rule contract identity failed".to_string());
    }

    let required_fields = contract
        .get("required_fields")
        .and_then(serde_json::Value::as_array)
        .ok_or("reserve required fields")?;
    let observed = required_fields
        .iter()
        .map(|row| string_field(row, "field_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    for required in [
        "reserve_contribution",
        "reserve_withdrawal",
        "reserve_balance",
        "reserve_cap",
        "emergency_override_rule",
        "cyclical_shortfall_draw_rule",
        "surplus_routing_rule",
        "future_year_payback_rule",
        "public_rounding_residual_line",
    ] {
        if !observed.contains(required) {
            return Err(format!("reserve required field missing {required}"));
        }
    }
    for row in required_fields {
        if row.get("required").and_then(serde_json::Value::as_bool) != Some(true)
            || !row
                .get("initial_value")
                .is_some_and(serde_json::Value::is_null)
        {
            return Err("reserve required fields must be required/null".to_string());
        }
    }

    let rules = contract
        .get("contract_rules")
        .and_then(serde_json::Value::as_object)
        .ok_or("reserve contract rules")?;
    for true_flag in [
        "over_the_cycle_reserve_required",
        "cyclical_shortfall_draws_reserve_before_rate_increase_or_benefit_cut",
        "surplus_routes_to_reserve_then_debt_before_discretionary_rate_cut",
        "emergency_override_requires_explicit_rule",
        "emergency_deferral_cap_required",
        "future_year_payback_required",
        "rounding_residual_must_be_explicit",
        "missing_values_remain_null",
    ] {
        if rules.get(true_flag).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!("reserve rule true flag failed {true_flag}"));
        }
    }
    if rules
        .get("solver_ready")
        .and_then(serde_json::Value::as_bool)
        != Some(false)
    {
        return Err("reserve rule solver_ready must be false".to_string());
    }

    let placeholders = contract
        .get("parameter_placeholders")
        .and_then(serde_json::Value::as_object)
        .ok_or("reserve parameter placeholders")?;
    for (field, value) in placeholders {
        if !value.is_null() {
            return Err(format!("reserve placeholder {field} must remain null"));
        }
    }

    let blocked = contract
        .get("blocked_until")
        .and_then(serde_json::Value::as_array)
        .ok_or("reserve blockers")?
        .iter()
        .filter_map(serde_json::Value::as_str)
        .collect::<BTreeSet<_>>();
    for required in [
        "reserve_contribution_series",
        "reserve_withdrawal_series",
        "reserve_balance_series",
        "reserve_cap_formula",
        "emergency_override_rule",
        "future_year_payback_schedule",
        "public_rounding_residual_line",
        "role_review_of_parameter_choices",
    ] {
        if !blocked.contains(required) {
            return Err(format!("reserve blocker missing {required}"));
        }
    }

    let claims = contract
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("reserve claims")?;
    for (field, value) in claims {
        let observed = value.as_bool().ok_or("reserve claim bool")?;
        if field == "reserve_rule_contract_published" {
            if !observed {
                return Err("reserve contract publish flag must be true".to_string());
            }
        } else if observed {
            return Err(format!("reserve public claim {field} must be false"));
        }
    }

    let boundary = string_field(&contract, "non_claim_boundary")?;
    for required in [
        "reserve rule contract",
        "not reserve parameters",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a public rate card",
        "not a tax proposal",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !boundary.contains(required) {
            return Err(format!("reserve boundary missing {required}"));
        }
    }

    let reader = fs::read_to_string(root.join(RESERVE_RULE_CONTRACT_READER_PATH))
        .map_err(|e| e.to_string())?;
    for required in [
        RESERVE_RULE_CONTRACT_JSON_PATH,
        "does not choose numeric reserve parameters",
        "reserve contribution",
        "reserve withdrawal",
        "reserve balance",
        "reserve cap",
        "emergency override rule",
        "future-year payback rule",
        "public rounding residual line",
        "cyclical shortfall draws the reserve before any rate increase or benefit cut",
        "not reserve parameters",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!("reserve reader missing {required}"));
        }
    }

    Ok(())
}

fn validate_reserve_parameter_readiness_gate(root: &Path) -> Result<(), String> {
    for path in [
        RESERVE_PARAMETER_READINESS_GATE_JSON_PATH,
        RESERVE_PARAMETER_READINESS_GATE_SCHEMA_PATH,
        RESERVE_PARAMETER_READINESS_GATE_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing reserve parameter readiness artifact: {path}"
            ));
        }
    }

    let text = fs::read_to_string(root.join(RESERVE_PARAMETER_READINESS_GATE_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let gate: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&gate, "record_id")? != "reserve-parameter-readiness-gate:v1"
        || string_field(&gate, "record_family")? != "reserve_parameter_readiness_gate"
        || int_field(&gate, "pulse")? != 103
        || string_field(&gate, "reserve_rule_contract_path")? != RESERVE_RULE_CONTRACT_JSON_PATH
        || string_field(&gate, "solver_input_inventory_path")? != SOLVER_INPUT_INVENTORY_JSON_PATH
        || string_field(&gate, "program_lane_target_cost_contract_path")?
            != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
        || string_field(&gate, "balance_guardrail_path")?
            != "docs/research/2026-06-23-balance-rule-guardrail-spec.md"
        || string_field(&gate, "rate_adjustment_operating_model_path")?
            != "docs/research/2026-06-24-rate-adjustment-operating-model.md"
    {
        return Err("reserve parameter readiness identity failed".to_string());
    }

    let decisions = gate
        .get("required_parameter_decisions")
        .and_then(serde_json::Value::as_array)
        .ok_or("reserve parameter decisions")?;
    let observed = decisions
        .iter()
        .map(|row| string_field(row, "decision_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected = [
        "reserve_contribution_formula",
        "reserve_withdrawal_rule",
        "reserve_balance_series",
        "reserve_cap_formula",
        "emergency_override_threshold",
        "emergency_deferral_cap",
        "future_year_payback_schedule",
        "public_rounding_residual_line",
        "source_vintage_binding",
        "role_review_of_parameter_choices",
    ]
    .into_iter()
    .map(str::to_string)
    .collect::<BTreeSet<_>>();
    if observed != expected || decisions.len() != expected.len() {
        return Err("reserve parameter decision set failed".to_string());
    }
    for row in decisions {
        if row.get("required").and_then(serde_json::Value::as_bool) != Some(true)
            || row.get("ready").and_then(serde_json::Value::as_bool) != Some(false)
            || !row
                .get("current_value")
                .is_some_and(serde_json::Value::is_null)
        {
            return Err("reserve parameter decisions must be required/false/null".to_string());
        }
        let blockers = row
            .get("blockers")
            .and_then(serde_json::Value::as_array)
            .ok_or("reserve parameter blockers")?;
        if blockers.is_empty() {
            return Err("reserve parameter decisions must name blockers".to_string());
        }
    }

    let invariants = gate
        .get("accounting_invariants")
        .and_then(serde_json::Value::as_object)
        .ok_or("reserve parameter invariants")?;
    for required in [
        "missing_values_remain_null",
        "reserves_do_not_create_savings",
        "reserve_contributions_are_positive_outlays",
        "reserve_withdrawals_are_explicit_financing_sources",
        "emergency_overrides_require_explicit_rule",
        "future_year_payback_required",
        "public_rounding_residual_must_be_explicit",
        "trust_funds_remain_separate",
        "net_interest_remains_endogenous",
    ] {
        if invariants
            .get(required)
            .and_then(serde_json::Value::as_bool)
            != Some(true)
        {
            return Err(format!("reserve parameter invariant failed {required}"));
        }
    }

    let gate_status = gate
        .get("gate_status")
        .and_then(serde_json::Value::as_object)
        .ok_or("reserve parameter gate status")?;
    for (field, value) in gate_status {
        if value.as_bool() != Some(false) {
            return Err(format!(
                "reserve parameter gate status {field} must be false"
            ));
        }
    }

    let claims = gate
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("reserve parameter claims")?;
    for (field, value) in claims {
        let observed = value.as_bool().ok_or("reserve parameter claim bool")?;
        if field == "reserve_parameter_readiness_gate_published" {
            if !observed {
                return Err("reserve parameter readiness publish flag must be true".to_string());
            }
        } else if observed {
            return Err(format!(
                "reserve parameter public claim {field} must be false"
            ));
        }
    }

    let boundary = string_field(&gate, "non_claim_boundary")?;
    for required in [
        "reserve-parameter readiness gate",
        "not reserve parameters",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a public rate card",
        "not a tax proposal",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !boundary.contains(required) {
            return Err(format!("reserve parameter boundary missing {required}"));
        }
    }

    let reader = fs::read_to_string(root.join(RESERVE_PARAMETER_READINESS_GATE_READER_PATH))
        .map_err(|e| e.to_string())?;
    for required in [
        RESERVE_PARAMETER_READINESS_GATE_JSON_PATH,
        "does not choose numeric reserve parameters",
        "reserve contribution formula",
        "reserve withdrawal rule",
        "reserve balance series",
        "reserve cap formula",
        "emergency override threshold",
        "emergency deferral cap",
        "future-year payback schedule",
        "public rounding residual line",
        "source vintage binding",
        "role review of parameter choices",
        "Reserve contributions are positive outlays",
        "Reserve withdrawals are explicit financing sources",
        "Trust funds remain separate",
        "net interest remains endogenous",
        "not reserve parameters",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!("reserve parameter reader missing {required}"));
        }
    }

    Ok(())
}

fn validate_net_interest_formula_contract(root: &Path) -> Result<(), String> {
    for path in [
        NET_INTEREST_FORMULA_CONTRACT_JSON_PATH,
        NET_INTEREST_FORMULA_CONTRACT_SCHEMA_PATH,
        NET_INTEREST_FORMULA_CONTRACT_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!("missing net-interest formula artifact: {path}"));
        }
    }

    let text = fs::read_to_string(root.join(NET_INTEREST_FORMULA_CONTRACT_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let contract: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&contract, "record_id")? != "net-interest-formula-contract:v1"
        || string_field(&contract, "record_family")? != "net_interest_formula_contract"
        || int_field(&contract, "pulse")? != 104
        || string_field(&contract, "solver_input_inventory_path")?
            != SOLVER_INPUT_INVENTORY_JSON_PATH
        || string_field(&contract, "program_lane_target_cost_contract_path")?
            != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
        || string_field(&contract, "solver_accounting_readiness_gate_path")?
            != SOLVER_ACCOUNTING_READINESS_GATE_JSON_PATH
        || string_field(&contract, "balance_guardrail_path")?
            != "docs/research/2026-06-23-balance-rule-guardrail-spec.md"
        || string_field(&contract, "rate_adjustment_operating_model_path")?
            != "docs/research/2026-06-24-rate-adjustment-operating-model.md"
    {
        return Err("net-interest formula identity failed".to_string());
    }

    let formula = contract
        .get("formula_identity")
        .ok_or("net-interest formula identity")?;
    for required in [
        (
            "primary_balance",
            "total_federal_receipts - primary_outlays",
        ),
        (
            "deficit",
            "primary_outlays + net_interest - total_federal_receipts",
        ),
        (
            "debt_t",
            "debt_t_minus_1 + deficit_t + explicit_other_financing_t",
        ),
    ] {
        if string_field(formula, required.0)? != required.1 {
            return Err(format!("net-interest formula {} failed", required.0));
        }
    }
    for required in [
        "sum_over_maturity_buckets",
        "debt_stock_bucket_t_minus_1",
        "effective_rate_bucket_t",
        "interest_receipts_t",
        "After any primary-balance change",
        "recompute deficit, debt, maturity-bucket debt stock, and subsequent net interest",
    ] {
        let formula_text = format!(
            "{} {}",
            string_field(formula, "net_interest_t")?,
            string_field(formula, "iteration_rule")?
        );
        if !formula_text.contains(required) {
            return Err(format!("net-interest formula text missing {required}"));
        }
    }

    let inputs = contract
        .get("required_inputs")
        .and_then(serde_json::Value::as_array)
        .ok_or("net-interest required inputs")?;
    let observed = inputs
        .iter()
        .map(|row| string_field(row, "input_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected = [
        "baseline_debt_stock",
        "baseline_net_interest",
        "maturity_bucket_schedule",
        "effective_rate_path_by_bucket",
        "new_borrowing_timing_rule",
        "interest_receipts_treatment",
        "explicit_other_financing_series",
        "primary_balance_feedback_test_fixture",
    ]
    .into_iter()
    .map(str::to_string)
    .collect::<BTreeSet<_>>();
    if observed != expected || inputs.len() != expected.len() {
        return Err("net-interest input set failed".to_string());
    }
    for row in inputs {
        if row.get("required").and_then(serde_json::Value::as_bool) != Some(true)
            || row.get("ready").and_then(serde_json::Value::as_bool) != Some(false)
            || !row.get("value").is_some_and(serde_json::Value::is_null)
        {
            return Err("net-interest inputs must be required/false/null".to_string());
        }
        let blockers = row
            .get("blockers")
            .and_then(serde_json::Value::as_array)
            .ok_or("net-interest blockers")?;
        if blockers.is_empty() {
            return Err("net-interest inputs must name blockers".to_string());
        }
    }

    let rules = contract
        .get("contract_rules")
        .and_then(serde_json::Value::as_object)
        .ok_or("net-interest rules")?;
    for required in [
        "net_interest_is_endogenous",
        "net_interest_cannot_be_cut_directly",
        "primary_change_must_change_subsequent_debt",
        "primary_change_must_change_subsequent_interest",
        "maturity_and_rate_paths_must_be_explicit",
        "interest_receipts_must_be_explicit",
        "explicit_other_financing_must_be_explicit",
        "missing_values_remain_null",
    ] {
        if rules.get(required).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!("net-interest rule failed {required}"));
        }
    }
    if rules
        .get("solver_ready")
        .and_then(serde_json::Value::as_bool)
        != Some(false)
    {
        return Err("net-interest solver_ready must be false".to_string());
    }

    let regression = contract
        .get("regression_test_contract")
        .ok_or("net-interest regression contract")?;
    if regression
        .get("required")
        .and_then(serde_json::Value::as_bool)
        != Some(true)
        || regression.get("ready").and_then(serde_json::Value::as_bool) != Some(false)
        || string_field(regression, "test_name")?
            != "primary_balance_change_recomputes_debt_and_interest"
        || !regression
            .get("test_fixture_path")
            .is_some_and(serde_json::Value::is_null)
    {
        return Err("net-interest regression contract failed".to_string());
    }
    let blocked = regression
        .get("blocked_until")
        .and_then(serde_json::Value::as_array)
        .ok_or("net-interest regression blockers")?
        .iter()
        .filter_map(serde_json::Value::as_str)
        .collect::<BTreeSet<_>>();
    for required in [
        "baseline_debt_stock",
        "maturity_bucket_schedule",
        "effective_rate_path_by_bucket",
        "primary_balance_feedback_test_fixture",
    ] {
        if !blocked.contains(required) {
            return Err(format!(
                "net-interest regression blocker missing {required}"
            ));
        }
    }

    let claims = contract
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("net-interest claims")?;
    for (field, value) in claims {
        let observed = value.as_bool().ok_or("net-interest claim bool")?;
        if field == "net_interest_formula_contract_published" {
            if !observed {
                return Err("net-interest formula publish flag must be true".to_string());
            }
        } else if observed {
            return Err(format!("net-interest public claim {field} must be false"));
        }
    }

    let boundary = string_field(&contract, "non_claim_boundary")?;
    for required in [
        "net-interest formula contract",
        "not a net-interest path",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a public rate card",
        "not a tax proposal",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !boundary.contains(required) {
            return Err(format!("net-interest boundary missing {required}"));
        }
    }

    let reader = fs::read_to_string(root.join(NET_INTEREST_FORMULA_CONTRACT_READER_PATH))
        .map_err(|e| e.to_string())?;
    for required in [
        NET_INTEREST_FORMULA_CONTRACT_JSON_PATH,
        "does not publish a debt path",
        "baseline debt stock",
        "baseline net interest",
        "maturity bucket schedule",
        "effective rate path by bucket",
        "new borrowing timing rule",
        "interest receipts treatment",
        "explicit other financing series",
        "primary-balance feedback test fixture",
        "Net interest is endogenous",
        "Net interest cannot be cut directly",
        "After any primary-balance change",
        "recompute deficit, debt, maturity-bucket debt stock, and subsequent net interest",
        "primary_balance_change_recomputes_debt_and_interest",
        "fixture path is still null",
        "not a net-interest path",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!("net-interest reader missing {required}"));
        }
    }

    Ok(())
}

