        || string_field(&frontier, "fiscal_package_def_bridge_path")?
            != FISCAL_PACKAGE_DEF_BRIDGE_JSON_PATH
        || string_field(&frontier, "pay_level_3_control_path")? != PAY_LEVEL_3_CONTROL_JSON_PATH
        || string_field(&frontier, "pay_level_4_audit_path")? != PAY_LEVEL_4_AUDIT_JSON_PATH
