        || int_field(aggregate, "rev_level_6_revenue_dossiers_completed")? != 1
        || int_field(aggregate, "rev_f_planning_rate_cards_published")? != 1
        || int_field(aggregate, "rate_down_bundles_completed")? != 1
        || int_field(aggregate, "eight_track_catchup_levels_completed")? != 16
        || int_field(aggregate, "fifteen_track_integrated_reruns_completed")? != 1
        || int_field(aggregate, "rev_level_7_internal_certifications_completed")? != 1
        || int_field(aggregate, "official_score_handoffs_ready")? != 1
