        || int_field(aggregate, "targeted_spending_rate_waves_completed")? != 1
        || int_field(aggregate, "specific_spending_candidates_reviewed")? != 2
        || int_field(aggregate, "specific_spending_candidates_admitted")? != 0
        || int_field(aggregate, "external_submission_waves_active")? != 0
