        || int_field(aggregate, "next_level_a_work_items_completed")? != 15
        || int_field(aggregate, "next_level_b_work_items_started")? != 15
        || int_field(aggregate, "next_level_b_work_items_completed")? != 15
        || int_field(aggregate, "batch_2_tracks_two_levels_completed")? != 8
