fn validate_fiscally_decisive_advancement_bundle(root: &Path) -> Result<(), String> {
    let required_paths = [
        REV_LEVEL_1_GUARDED_CLOSURE_JSON_PATH,
        "data/derived/breadth_benchmark_matrix/rev_level_1_guarded_proxy_closure.schema.md",
        "docs/reading/rev-level-1-guarded-proxy-closure.md",
        "reviews/2026-07-27-rev-level-1-guarded-proxy-closure-role-review.md",
        FISCALLY_DECISIVE_LEVEL_1_JSON_PATH,
        "data/derived/breadth_benchmark_matrix/fiscally_decisive_track_level_1_candidate_envelopes.schema.md",
        "docs/reading/fiscally-decisive-track-level-1-candidate-envelopes.md",
        "reviews/2026-07-27-fiscally-decisive-track-level-1-candidate-envelopes-role-review.md",
        FISCALLY_DECISIVE_LEVEL_2_JSON_PATH,
        "data/derived/breadth_benchmark_matrix/fiscally_decisive_track_level_2_dependency_rerun.schema.md",
        "docs/reading/fiscally-decisive-track-level-2-dependency-rerun.md",
        "reviews/2026-07-27-fiscally-decisive-track-level-2-dependency-rerun-role-review.md",
    ];
    for path in required_paths {
        if !root.join(path).is_file() {
            return Err(format!("missing fiscally decisive bundle artifact: {path}"));
        }
    }

    let rev = read_json_artifact(root, REV_LEVEL_1_GUARDED_CLOSURE_JSON_PATH)?;
    let selected = rev
        .get("selected_planning_case")
        .ok_or("REV guarded selected planning case")?;
    let caveats = rev
        .get("required_caveats")
        .ok_or("REV guarded required caveats")?;
    let closure = rev
        .get("closure_decision")
        .ok_or("REV guarded closure decision")?;
    if int_field(&rev, "pulse")? != 422
        || int_field(selected, "annual_spending_reduction_assumption_millions")? != 500_000
        || (number_field(selected, "proxy_uplift_points")? - 2.760).abs() > 0.0001
        || !bool_field(caveats, "spending_correction_is_assumed_not_scored")?
        || !bool_field(caveats, "proxy_is_not_jct_or_cbo_score")?
        || !bool_field(caveats, "nonlinear_behavior_not_modeled")?
        || !bool_field(caveats, "distribution_by_income_not_quantified")?
        || !bool_field(closure, "bounded_planning_objective_complete")?
        || bool_field(closure, "assigned_rate_ready")?
        || bool_field(closure, "core_n_rate_card_ready")?
        || bool_field(closure, "rev_f_may_start")?
    {
        return Err("REV guarded proxy closure failed".to_string());
    }
    validate_blocked_outputs_null(&rev, "REV guarded proxy closure")?;

    let level_1 = read_json_artifact(root, FISCALLY_DECISIVE_LEVEL_1_JSON_PATH)?;
    let level_1_rows = level_1
        .get("track_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("fiscally decisive Level-1 rows")?;
    let level_1_prefixes = level_1_rows
        .iter()
        .map(|row| string_field(row, "prefix"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    if int_field(&level_1, "pulse")? != 423
        || level_1_rows.len() != 5
        || level_1_prefixes
            != BTreeSet::from([
                "DEF".to_string(),
                "HLT".to_string(),
                "NET".to_string(),
                "OAS".to_string(),
                "PAY".to_string(),
            ])
    {
        return Err("fiscally decisive Level-1 envelope set failed".to_string());
    }
    let pay = level_1_rows
        .iter()
        .find(|row| string_field(row, "prefix").ok().as_deref() == Some("PAY"))
        .ok_or("PAY Level-1 envelope")?;
    let net = level_1_rows
        .iter()
        .find(|row| string_field(row, "prefix").ok().as_deref() == Some("NET"))
        .ok_or("NET Level-1 envelope")?;
    if !pay
        .get("recoverable_savings")
        .is_some_and(serde_json::Value::is_null)
        || int_field(net, "mechanical_full_year_carry_sensitivity_millions")? != 17_045
        || bool_field(net, "timing_and_maturity_modeled")?
    {
        return Err("PAY or NET Level-1 caveat failed".to_string());
    }
    validate_blocked_outputs_null(&level_1, "fiscally decisive Level-1")?;

    let level_2 = read_json_artifact(root, FISCALLY_DECISIVE_LEVEL_2_JSON_PATH)?;
    let level_2_rows = level_2
        .get("track_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("fiscally decisive Level-2 rows")?;
    if int_field(&level_2, "pulse")? != 424 || level_2_rows.len() != 5 {
        return Err("fiscally decisive Level-2 row set failed".to_string());
    }
    for row in level_2_rows {
        if string_field(row, "completion_class")?.starts_with("reviewed_reblock") == false
            || bool_field(row, "e_rerun_output_ready")?
            || bool_field(row, "f_may_start")?
        {
            return Err(format!(
                "fiscally decisive Level-2 caveat failed for {}",
                string_field(row, "prefix")?
            ));
        }
    }
    validate_blocked_outputs_null(&level_2, "fiscally decisive Level-2")?;
    Ok(())
}

fn validate_hlt_fiscal_package_conversion(root: &Path) -> Result<(), String> {
    let required_paths = [
        HLT_LEVEL_3_MA_PROXY_JSON_PATH,
        "data/derived/breadth_benchmark_matrix/hlt_level_3_ma_benchmark_current_law_scale_proxy.schema.md",
        "docs/reading/hlt-level-3-ma-benchmark-current-law-scale-proxy.md",
        "reviews/2026-07-27-hlt-level-3-ma-benchmark-current-law-scale-proxy-role-review.md",
        HLT_LEVEL_4_FLOOR_AUDIT_JSON_PATH,
        "data/derived/breadth_benchmark_matrix/hlt_level_4_ma_benchmark_beneficiary_floor_audit.schema.md",
        "docs/reading/hlt-level-4-ma-benchmark-beneficiary-floor-audit.md",
        "reviews/2026-07-27-hlt-level-4-ma-benchmark-beneficiary-floor-audit-role-review.md",
        FISCAL_PACKAGE_HLT_BRIDGE_JSON_PATH,
        "data/derived/breadth_benchmark_matrix/fiscal_package_hlt_contribution_bridge.schema.md",
        "docs/reading/fiscal-package-hlt-contribution-bridge.md",
        "reviews/2026-07-27-fiscal-package-hlt-contribution-bridge-role-review.md",
    ];
    for path in required_paths {
        if !root.join(path).is_file() {
            return Err(format!("missing HLT fiscal conversion artifact: {path}"));
        }
    }

    let proxy = read_json_artifact(root, HLT_LEVEL_3_MA_PROXY_JSON_PATH)?;
    let method = proxy.get("proxy_method").ok_or("HLT proxy method")?;
    let proxy_rows = proxy
        .get("annual_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("HLT proxy annual rows")?;
    let proxy_summary = proxy.get("proxy_summary").ok_or("HLT proxy summary")?;
    let proxy_decision = proxy.get("decision").ok_or("HLT proxy decision")?;
    if int_field(&proxy, "pulse")? != 425
        || proxy_rows.len() != 9
        || bool_field(method, "old_denominator_is_exact_option_baseline")?
        || bool_field(method, "perimeter_match_complete")?
        || bool_field(method, "formal_cbo_rescore")?
        || (number_field(proxy_summary, "fy2027_2034_scale_proxy_billions")? - 497.044).abs()
            > 0.001
        || (number_field(proxy_summary, "fy2027_2034_average_annual_proxy_billions")? - 62.131)
            .abs()
            > 0.001
        || int_field(proxy_summary, "fy2026_proxy_billions")? != 0
        || bool_field(proxy_decision, "formal_current_law_rescore_ready")?
        || bool_field(proxy_decision, "candidate_admitted_to_package")?
        || bool_field(proxy_decision, "hlt_f_may_start")?
    {
        return Err("HLT Level-3 scale proxy failed".to_string());
    }
    for row in proxy_rows {
        if !row
            .get("admitted_package_reduction_billions")
            .is_some_and(serde_json::Value::is_null)
        {
            return Err("HLT Level-3 admitted proxy must remain null".to_string());
        }
    }
    validate_blocked_outputs_null(&proxy, "HLT Level-3 scale proxy")?;

    let audit = read_json_artifact(root, HLT_LEVEL_4_FLOOR_AUDIT_JSON_PATH)?;
    let floor_rows = audit
        .get("floor_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("HLT floor rows")?;
    let candidate = audit
        .get("candidate_decision")
        .ok_or("HLT candidate decision")?;
    let dispositions = floor_rows
        .iter()
        .map(|row| string_field(row, "disposition"))
        .collect::<Result<Vec<_>, _>>()?;
    if int_field(&audit, "pulse")? != 426
        || floor_rows.len() != 8
        || dispositions
            .iter()
            .filter(|value| *value == "directional_pass")
            .count()
            != 1
        || dispositions
            .iter()
            .filter(|value| *value == "adverse_fail")
            .count()
            != 2
        || dispositions
            .iter()
            .filter(|value| *value == "required_blocked")
            .count()
            != 5
        || bool_field(candidate, "all_required_floors_pass")?
        || bool_field(candidate, "candidate_admitted_to_spending_package")?
        || bool_field(candidate, "proxy_may_be_counted_as_savings")?
        || bool_field(candidate, "hlt_f_may_start")?
    {
        return Err("HLT Level-4 beneficiary floor audit failed".to_string());
    }
    validate_blocked_outputs_null(&audit, "HLT Level-4 floor audit")?;

    let bridge = read_json_artifact(root, FISCAL_PACKAGE_HLT_BRIDGE_JSON_PATH)?;
    let rows = bridge
        .get("annual_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("HLT package bridge rows")?;
    let findings = bridge.get("scale_findings").ok_or("HLT scale findings")?;
    let decision = bridge.get("decision").ok_or("HLT package decision")?;
    if int_field(&bridge, "pulse")? != 427
        || rows.len() != 9
        || int_field(findings, "fy2026_hlt_contribution_billions")? != 0
        || (number_field(findings, "fy2026_rev_proxy_uplift_points_after_hlt")? - 2.760).abs()
            > 0.0001
        || (number_field(
            findings,
            "fy2027_2034_average_mechanical_target_share_percent",
        )? - 12.426)
            .abs()
            > 0.001
        || bool_field(decision, "hlt_changes_fy2026_rate_case")?
        || bool_field(decision, "hlt_candidate_floor_admitted")?
        || bool_field(decision, "package_spending_correction_ready")?
        || string_field(decision, "next_decisive_track")? != "DEF"
    {
        return Err("fiscal-package HLT contribution bridge failed".to_string());
    }
    for row in rows {
        if !row
            .get("admitted_hlt_contribution_billions")
            .is_some_and(serde_json::Value::is_null)
            || !row
                .get("admitted_remaining_target_billions")
                .is_some_and(serde_json::Value::is_null)
        {
            return Err("HLT package admitted values must remain null".to_string());
        }
    }
    validate_blocked_outputs_null(&bridge, "fiscal-package HLT bridge")?;
    Ok(())
}

fn validate_def_fiscal_package_conversion(root: &Path) -> Result<(), String> {
    let required_paths = [
        DEF_LEVEL_3_SCALE_BRIDGE_JSON_PATH,
        "data/derived/breadth_benchmark_matrix/def_level_3_defense_current_law_scale_bridge.schema.md",
        "docs/reading/def-level-3-defense-current-law-scale-bridge.md",
        "reviews/2026-07-27-def-level-3-defense-current-law-scale-bridge-role-review.md",
        DEF_LEVEL_4_ALLOCATION_AUDIT_JSON_PATH,
        "data/derived/breadth_benchmark_matrix/def_level_4_force_readiness_allocation_audit.schema.md",
        "docs/reading/def-level-4-force-readiness-allocation-audit.md",
        "reviews/2026-07-27-def-level-4-force-readiness-allocation-audit-role-review.md",
        FISCAL_PACKAGE_DEF_BRIDGE_JSON_PATH,
        "data/derived/breadth_benchmark_matrix/fiscal_package_def_contribution_bridge.schema.md",
        "docs/reading/fiscal-package-def-contribution-bridge.md",
        "reviews/2026-07-27-fiscal-package-def-contribution-bridge-role-review.md",
    ];
    for path in required_paths {
        if !root.join(path).is_file() {
            return Err(format!("missing DEF fiscal conversion artifact: {path}"));
        }
    }

    let bridge = read_json_artifact(root, DEF_LEVEL_3_SCALE_BRIDGE_JSON_PATH)?;
    let method = bridge
        .get("comparison_method")
        .ok_or("DEF comparison method")?;
    let rows = bridge
        .get("annual_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("DEF scale annual rows")?;
    let summary = bridge.get("scale_summary").ok_or("DEF scale summary")?;
    let decision = bridge.get("decision").ok_or("DEF scale decision")?;
    if int_field(&bridge, "pulse")? != 428
        || rows.len() != 9
        || bool_field(method, "perimeter_match_complete")?
        || bool_field(method, "annual_values_are_rescaled")?
        || bool_field(method, "formal_cbo_rescore")?
        || int_field(summary, "fy2026_2034_official_option_outlay_billions")? != 959
        || (number_field(summary, "average_annual_official_option_billions")? - 106.556).abs()
            > 0.001
        || int_field(summary, "fy2026_official_option_billions")? != 15
        || bool_field(decision, "formal_current_law_rescore_ready")?
        || bool_field(decision, "candidate_admitted_to_package")?
        || bool_field(decision, "def_f_may_start")?
    {
        return Err("DEF Level-3 scale bridge failed".to_string());
    }
    let option_sum = rows.iter().try_fold(0.0, |sum, row| {
        number_field(row, "official_option_outlay_reduction_billions").map(|value| sum + value)
    })?;
    if (option_sum - 959.0).abs() > 0.001 {
        return Err("DEF official annual option sum failed".to_string());
    }
    for row in rows {
        if !row
            .get("admitted_package_reduction_billions")
            .is_some_and(serde_json::Value::is_null)
        {
            return Err("DEF Level-3 admitted value must remain null".to_string());
        }
    }
    validate_blocked_outputs_null(&bridge, "DEF Level-3 scale bridge")?;

    let audit = read_json_artifact(root, DEF_LEVEL_4_ALLOCATION_AUDIT_JSON_PATH)?;
    let gates = audit
        .get("allocation_gate_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("DEF allocation gates")?;
    let candidate = audit
        .get("candidate_decision")
        .ok_or("DEF candidate decision")?;
    if int_field(&audit, "pulse")? != 429
        || gates.len() != 8
        || gates.iter().any(|row| {
            !string_field(row, "disposition").is_ok_and(|value| value == "required_blocked")
        })
        || int_field(candidate, "required_blocked_count")? != 8
        || bool_field(candidate, "all_required_gates_pass")?
        || bool_field(candidate, "candidate_admitted_to_spending_package")?
        || bool_field(candidate, "official_option_may_be_counted_as_savings")?
        || bool_field(candidate, "def_f_may_start")?
    {
        return Err("DEF Level-4 allocation audit failed".to_string());
    }
    validate_blocked_outputs_null(&audit, "DEF Level-4 allocation audit")?;

    let package = read_json_artifact(root, FISCAL_PACKAGE_DEF_BRIDGE_JSON_PATH)?;
    let package_rows = package
        .get("annual_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("DEF package rows")?;
    let findings = package
        .get("scale_findings")
        .ok_or("DEF package findings")?;
    let package_decision = package.get("decision").ok_or("DEF package decision")?;
    if int_field(&package, "pulse")? != 430
        || package_rows.len() != 9
        || int_field(findings, "fy2026_def_option_billions")? != 15
        || (number_field(findings, "fy2026_rev_proxy_uplift_points_after_def")? - 2.760).abs()
            > 0.0001
        || (number_field(
            findings,
            "fy2026_2034_average_hlt_def_mechanical_target_share_percent",
        )? - 32.357)
            .abs()
            > 0.001
        || bool_field(package_decision, "def_changes_fy2026_rate_case")?
        || bool_field(package_decision, "def_candidate_allocation_admitted")?
        || bool_field(package_decision, "package_spending_correction_ready")?
        || string_field(package_decision, "next_decisive_track")? != "PAY"
    {
        return Err("fiscal-package DEF contribution bridge failed".to_string());
    }
    for row in package_rows {
        for field in [
            "admitted_def_contribution_billions",
            "admitted_combined_contribution_billions",
            "admitted_remaining_target_billions",
        ] {
            if !row.get(field).is_some_and(serde_json::Value::is_null) {
                return Err(format!("DEF package {field} must remain null"));
            }
        }
    }
    validate_blocked_outputs_null(&package, "fiscal-package DEF bridge")?;
    Ok(())
}

