        || string_field(usda_support, "dedicated_reader_path")?
            != INCOME_SECURITY_FAMILY_FOOD_HARDSHIP_NUTRITION_CAPTURE_GAP_READER_PATH
        || int_field(usda_support, "fns_snap_raw_file_count")? != 7
