    #[test]
    fn rev_level_7_response_state_machine_accepts_only_custodied_transitions() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let mut intake =
            read_json_artifact(&root, REV_LEVEL_7_EXTERNAL_RESPONSE_INTAKE_JSON_PATH).unwrap();
        let cover_path = "docs/reading/rev-level-7-external-submission-cover-memo.md";
        let spec_path = REV_LEVEL_7_POLICY_SPEC_JSON_PATH;
        let workbook_path = REV_LEVEL_7_SCORE_WORKBOOK_JSON_PATH;
        let cover_sha = sha256_file(&root.join(cover_path)).unwrap();
        let spec_sha = sha256_file(&root.join(spec_path)).unwrap();
        let workbook_sha = sha256_file(&root.join(workbook_path)).unwrap();

        intake["status"] = serde_json::json!("official_response_received_pending_review");
        intake["submission_receipt"] = serde_json::json!({
            "bundle_id": "cc2718b3cd4a4723eba9846b29cc8335b4e94bab70c8783871ee8caa81a61be5",
            "bundle_sha256": "cdf3eb905736ca0285733e794ccb67a29f1a7df77244e5658a5f30f1b69ec772",
            "requesting_office": "synthetic authorized office fixture",
            "authorized_sender": "synthetic sender fixture",
            "recipient_office": "Joint Committee on Taxation",
            "recipient_contact": "synthetic recipient fixture",
            "channel": "synthetic secure channel fixture",
            "transmitted_at": "2026-07-27T00:00:00Z",
            "receipt_id": "synthetic-receipt-fixture",
            "receipt_evidence_path": cover_path,
            "receipt_evidence_sha256": cover_sha
        });
        intake["response_identity"] = serde_json::json!({
            "responding_office": "Joint Committee on Taxation",
            "response_type": "synthetic structural test fixture",
            "response_date": "2026-07-27",
            "response_identifier": "synthetic-response-fixture",
            "legislative_text_identifier": "synthetic-text-fixture",
            "legislative_text_sha256": cover_sha,
            "baseline_title": "synthetic baseline fixture",
            "baseline_vintage": "2026-07-27",
            "law_cutoff": "2026-07-27",
            "budget_window": "FY2026-FY2035",
            "official_status_verified": true,
            "verification_evidence_path": cover_path,
            "verification_evidence_sha256": cover_sha
        });
        intake["response_assets"]["conventional_score_path"] = serde_json::json!({
            "path": spec_path,
            "sha256": spec_sha,
            "responding_office": "Joint Committee on Taxation",
            "document_identifier": "synthetic-score-fixture"
        });
        validate_rev_level_7_external_response_intake_record(
            &root,
            &intake,
            "cc2718b3cd4a4723eba9846b29cc8335b4e94bab70c8783871ee8caa81a61be5",
        )
        .unwrap();

        intake["status"] =
            serde_json::json!("authenticated_response_ready_for_rate_recertification");
        intake["response_assets"]["legislative_counsel_text_path"] = serde_json::json!({
            "path": cover_path,
            "sha256": cover_sha,
            "responding_office": "Office of the Legislative Counsel, U.S. House of Representatives",
            "document_identifier": "synthetic-legislative-text-fixture"
        });
        intake["response_assets"]["annual_score_data_path"] = serde_json::json!({
            "path": workbook_path,
            "sha256": workbook_sha,
            "responding_office": "Joint Committee on Taxation",
            "document_identifier": "synthetic-annual-data-fixture"
        });
        intake["annual_score_rows"] = serde_json::Value::Array(
            (2026..=2035)
                .map(|fiscal_year| {
                    serde_json::json!({
                        "fiscal_year": fiscal_year,
                        "official_conventional_revenue_billions": 1.0,
                        "official_spending_effect_billions": null,
                        "official_administration_cost_billions": null,
                        "official_macro_revenue_feedback_billions": null,
                        "official_primary_deficit_change_billions": null,
                        "official_net_interest_change_billions": null,
                        "official_total_deficit_change_billions": null,
                        "scope_dispositions": {
                            "official_conventional_revenue_billions": "reported",
                            "official_spending_effect_billions": "not_provided",
                            "official_administration_cost_billions": "not_provided",
                            "official_macro_revenue_feedback_billions": "not_provided",
                            "official_primary_deficit_change_billions": "not_provided",
                            "official_net_interest_change_billions": "not_provided",
                            "official_total_deficit_change_billions": "not_provided"
                        }
                    })
                })
                .collect(),
        );
        for value in intake["review"].as_object_mut().unwrap().values_mut() {
            *value = serde_json::Value::Bool(true);
        }
        validate_rev_level_7_external_response_intake_record(
            &root,
            &intake,
            "cc2718b3cd4a4723eba9846b29cc8335b4e94bab70c8783871ee8caa81a61be5",
        )
        .unwrap();

        intake["response_assets"]["annual_score_data_path"]["sha256"] =
            serde_json::json!("0".repeat(64));
        assert!(
            validate_rev_level_7_external_response_intake_record(
                &root,
                &intake,
                "cc2718b3cd4a4723eba9846b29cc8335b4e94bab70c8783871ee8caa81a61be5",
            )
            .is_err()
        );
    }

